mapper.update:
UPDATE note_comment
SET is_deleted = 1
WHERE id = #{commentId}

mapper.select:
SELECT nc.*,
       CASE WHEN ncl.username IS NOT NULL THEN 1 ELSE 0 END as isLikedByCurrentUser
FROM note_comment nc
    LEFT JOIN note_comment_like ncl ON nc.id = ncl.comment_id AND ncl.username = #{username}
WHERE note_id = #{noteId}
